INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '百化分', 'kp-xingce-data-calc-percent-convert', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "百化分"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "将百分数转化为对应的近似分数，化乘除为简易比例运算。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "最常用于“已知现期量和增长率，求增长量”的题目。也常用于计算比重或乘法估算。特征：含有带 % 的增长率或比重。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "当增长率 r ≈ 1/n 时，增长量公式可极度简化："}]}, {"type": "katexBlock", "attrs": {"content": "增长量 = \\frac{现期量 \\times r}{1+r} \\approx \\frac{现期量}{n+1}"}}, {"type": "katexBlock", "attrs": {"content": "减少量 = \\frac{现期量 \\times |r|}{1-|r|} \\approx \\frac{现期量}{n-1}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出含百分数的式子] --> B[在大脑百化分表中检索最接近的分数 1/n]\nB --> C{求增长量还是减少量?}\nC -- 增长量 --> D[公式化为: 现期量 / (n + 1)]\nC -- 减少量 --> E[公式化为: 现期量 / (n - 1)]\nD --> F[直接进行一步除法得出答案]\nE --> F"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年某地旅游收入 7240 亿元，同比增长 14.2%。求旅游收入增长了多少亿元？选项：A. 815  B. 905  C. 1028  D. 1205"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：求增长量，已知现期和 r。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "百化分转换：14.2% 极度接近 14.3% (即 1/7)。所以 n = 7。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "套用化简公式：因为是“增长”，分母为 n + 1 = 8。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "计算：7240 ÷ 8 = 905。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：直接选 B。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "生搬硬套死背表：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "考场上的数字不可能刚好是 14.3% 或 16.7%。遇到 14% 或者 17%，要敢于就近取 1/7 和 1/6。算出来的结果略微偏大或偏小，根据就近原则选最接近的选项即可。不要纠结那零点几个百分点。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "必须把 1/2 到 1/15 的百分数对应表默写到形成肌肉记忆。例如：1/6=16.7%，1/7=14.3%，1/8=12.5%，1/9=11.1%，1/11=9.1%。"}]}]}$$ AS jsonb), NULL, '百化分的核心考点与实战推导。', category_node.id, CAST('["资料分析", "百化分"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_calc_percent_convert", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
